'use strict';
// Cocos 3.x plugin-script versions of the platform kit (plugins-3x/*.plugin.js, generated by
// tools/make_plugin_scripts.py). Proves:
//   1. every plugin runs as a plain global script (no require/module/exports, like a Cocos 3.x plugin), in any
//      load order, and publishes globalThis.TikTokKit.<Name>; loading one twice keeps the first; a missing
//      dependency names the plugin to add;
//   2. the SAME rewarded-timing.test.js and kit.test.js cases pass on the plugin versions as on the 2.4 modules
//      (same case names, same counts, all passed);
//   3. make_plugin_scripts.py --check passes on this kit and fails on a copy where a plugin core, a 2.4 module,
//      tiktok-touch-3x.js or KIT_PARTS_3X.json was changed;
//   4. KIT_PARTS_3X.json wiring lines are valid JavaScript and their anchor matches a 3.x game.js exactly once.
// Node only; it does NOT prove a real phone (待真机复测).
var assert = require('assert'), fs = require('fs'), os = require('os'), path = require('path'), vm = require('vm');
var child = require('child_process');
var KIT = path.join(__dirname, '..');
var PLUGINS = path.join(KIT, 'plugins-3x');
var NAMES = ['PlatformConfig', 'TikTokMissionService', 'RewardedService', 'SaveStore', 'MissionFlow'];
var parts = JSON.parse(fs.readFileSync(path.join(KIT, 'parts-3x', 'KIT_PARTS_3X.json'), 'utf8'));
var results = [];
function test(name, run) {
  try { run(); results.push({name: name, status: 'passed'}); }
  catch (e) { results.push({name: name, status: 'failed', error: String(e && e.message || e)}); }
}
function pluginFile(name) { return path.join(PLUGINS, name + '.plugin.js'); }
function bareContext() {
  var ctx = {console: console, setTimeout: setTimeout, clearTimeout: clearTimeout, setInterval: setInterval,
    clearInterval: clearInterval, Promise: Promise, Date: Date, JSON: JSON, Math: Math};
  ctx.globalThis = ctx;
  return vm.createContext(ctx);
}
function runIn(ctx, names) {
  names.forEach(function (n) { vm.runInContext(fs.readFileSync(pluginFile(n), 'utf8'), ctx, {filename: n + '.plugin.js'}); });
  return ctx;
}

// ---- 1. plugin-script behaviour ----
test('plugins_run_as_global_scripts_in_reverse_order', function () {
  var ctx = runIn(bareContext(), NAMES.slice().reverse());
  assert.strictEqual(typeof ctx.require, 'undefined', 'no require in a plugin scope');
  NAMES.forEach(function (n) { assert.ok(n in ctx.TikTokKit, n + ' published'); });
  var R = ctx.TikTokKit.RewardedService, M = ctx.TikTokKit.MissionFlow;
  assert.strictEqual(typeof R, 'function'); assert.strictEqual(typeof R.prototype.request, 'function');
  assert.strictEqual(typeof M, 'function');
  assert.strictEqual(typeof ctx.TikTokKit.SaveStore, 'function');
  assert.strictEqual(typeof ctx.TikTokKit.TikTokMissionService, 'function');
  assert.strictEqual(typeof ctx.TikTokKit.PlatformConfig.growthReward, 'function');
});
test('dependencies_are_the_same_objects', function () {
  var ctx = runIn(bareContext(), NAMES);
  var a = ctx.TikTokKit.PlatformConfig, b = ctx.TikTokKit.PlatformConfig;
  assert.strictEqual(a, b, 'one module instance');
  assert.strictEqual(Object.getOwnPropertyDescriptor(ctx.TikTokKit, 'PlatformConfig').writable, false);
});
test('loading_a_plugin_twice_keeps_the_first', function () {
  var ctx = runIn(bareContext(), NAMES);
  var first = ctx.TikTokKit.RewardedService;
  runIn(ctx, ['RewardedService']);
  assert.strictEqual(ctx.TikTokKit.RewardedService, first);
});
test('missing_dependency_names_the_plugin_to_add', function () {
  var ctx = runIn(bareContext(), ['RewardedService']);
  assert.throws(function () { return ctx.TikTokKit.RewardedService; }, /PlatformConfig is not loaded .*RewardedService.*PlatformConfig\.plugin\.js/);
  runIn(ctx, ['PlatformConfig']);
  assert.strictEqual(typeof ctx.TikTokKit.RewardedService, 'function', 'works once the dependency is loaded');
});
test('plugins_loaded_through_a_commonjs_loader_still_publish_globals', function () {
  // a mini-game build may load plugin scripts with require(url): module/exports/require then exist in scope
  var ctx = bareContext();
  NAMES.forEach(function (n) {
    var fn = vm.runInContext('(function (exports, require, module) {' + fs.readFileSync(pluginFile(n), 'utf8') + '\n})', ctx);
    var mod = {exports: {}};
    fn.call(mod.exports, mod.exports, function () { throw new Error('host require must not be used'); }, mod);
    assert.deepStrictEqual(Object.keys(mod.exports), [], n + ' leaves the host module alone');
  });
  assert.strictEqual(typeof ctx.TikTokKit.RewardedService, 'function');
  assert.strictEqual(typeof ctx.TikTokKit.MissionFlow, 'function');
});
test('plugin_core_is_the_24_module_byte_for_byte', function () {
  NAMES.forEach(function (n) {
    var plugin = fs.readFileSync(pluginFile(n)), src = fs.readFileSync(path.join(KIT, 'assets', 'tiktok-platform', n + '.js'));
    var b = Buffer.from('// ---- BEGIN assets/tiktok-platform/' + n + '.js ----\n'), e = Buffer.from('// ---- END assets/tiktok-platform/' + n + '.js ----\n');
    var start = plugin.indexOf(b), end = plugin.indexOf(e);
    assert.ok(start >= 0 && end > start, n + ' markers');
    assert.ok(plugin.slice(start + b.length, end).equals(src), n + ' core differs from the 2.4 module');
  });
});

// ---- 2. the same cases on the plugin versions ----
var work = fs.mkdtempSync(path.join(os.tmpdir(), 'kit-plugins3x-'));
process.on('exit', function () { fs.rmSync(work, {recursive: true, force: true}); });
// A CommonJS shim that evaluates the plugin scripts as global scripts (vm.runInThisContext: no require/module)
// into a fresh globalThis.TikTokKit on every require, then exports the named module.
function shim(names, exportName) {
  var files = names.map(function (n) { return pluginFile(n); });
  return "'use strict';\nvar vm = require('vm'), fs = require('fs');\nvar FILES = " + JSON.stringify(files) + ";\n" +
    "var saved = Object.getOwnPropertyDescriptor(globalThis, 'TikTokKit');\ndelete globalThis.TikTokKit;\n" +
    "try {\n  FILES.forEach(function (f) { vm.runInThisContext(fs.readFileSync(f, 'utf8'), {filename: f}); });\n" +
    "  var kit = globalThis.TikTokKit;\n  module.exports = " + (exportName ? 'kit.' + exportName : 'kit') + ";\n" +
    "} finally {\n  delete globalThis.TikTokKit;\n  if (saved) Object.defineProperty(globalThis, 'TikTokKit', saved);\n}\n";
}
function runSuite(file, args, env) {
  var r = child.spawnSync(process.execPath, [path.join(__dirname, file)].concat(args || []),
    {encoding: 'utf8', timeout: 120000, env: Object.assign({}, process.env, env || {})});
  var out = null;
  try { out = JSON.parse(r.stdout.slice(r.stdout.indexOf('{'))); } catch (e) { out = null; }
  return {status: r.status, out: out, stderr: String(r.stderr).slice(0, 400)};
}
function sameCases(label, base, plug) {
  assert.ok(base.out && plug.out, label + ': suite output unreadable ' + plug.stderr);
  assert.strictEqual(base.status, 0, label + ' fails on the 2.4 modules');
  var names = function (o) { return o.results.map(function (x) { return x.name; }); };
  assert.deepStrictEqual(names(plug.out), names(base.out), label + ': different case list');
  var bad = plug.out.results.filter(function (x) { return x.status !== 'passed'; });
  assert.strictEqual(bad.length, 0, label + ' on plugins: ' + JSON.stringify(bad).slice(0, 600));
  assert.strictEqual(plug.status, 0);
  return plug.out.passed;
}
var counts = {};
test('rewarded_timing_cases_pass_on_RewardedService_plugin', function () {
  var file = path.join(work, 'RewardedService.js');
  fs.writeFileSync(file, shim(['MissionFlow', 'RewardedService', 'PlatformConfig'], 'RewardedService'));
  counts.rewarded_timing = sameCases('rewarded-timing', runSuite('rewarded-timing.test.js'), runSuite('rewarded-timing.test.js', [file]));
});
test('kit_cases_pass_on_plugin_modules', function () {
  var dir = path.join(work, 'kit');
  fs.mkdirSync(dir);
  fs.writeFileSync(path.join(dir, '_kit3x.js'), shim(NAMES.slice().reverse(), null));
  ['PlatformConfig', 'SaveStore', 'MissionFlow', 'TikTokMissionService', 'RewardedService'].forEach(function (n) {
    fs.writeFileSync(path.join(dir, n + '.js'), "'use strict';\nmodule.exports = require('./_kit3x.js')." + n + ';\n');
  });
  counts.kit = sameCases('kit.test', runSuite('kit.test.js'), runSuite('kit.test.js', [], {KIT_DIR: dir}));
});
// Control: the shared cases really run the plugin code. A broken plugin copy (no late-grant guard / wrong
// growth reward) must turn them red through the same shims.
test('shared_cases_fail_on_broken_plugin_copies', function () {
  var dir = path.join(work, 'broken');
  fs.mkdirSync(dir);
  NAMES.forEach(function (n) { fs.copyFileSync(pluginFile(n), path.join(dir, n + '.plugin.js')); });
  edit(path.join(dir, 'RewardedService.plugin.js'), "res && res.isEnded === true ? 'completed'", "res ? 'completed'");
  edit(path.join(dir, 'MissionFlow.plugin.js'), '(Number(draft.coins) || 0) + growth.growthReward()', '(Number(draft.coins) || 0) + 1');
  var keep = PLUGINS;
  PLUGINS = dir;
  try {
    fs.writeFileSync(path.join(dir, 'RewardedService.js'), shim(['RewardedService', 'PlatformConfig'], 'RewardedService'));
    fs.writeFileSync(path.join(dir, '_kit3x.js'), shim(NAMES, null));
    ['PlatformConfig', 'SaveStore', 'MissionFlow', 'TikTokMissionService', 'RewardedService'].forEach(function (n) {
      fs.writeFileSync(path.join(dir, n + '.js'), "'use strict';\nmodule.exports = require('./_kit3x.js')." + n + ';\n');
    });
  } finally { PLUGINS = keep; }
  var r = runSuite('rewarded-timing.test.js', [path.join(dir, 'RewardedService.js')]);
  assert.ok(r.status !== 0 && r.out && r.out.failed > 0, 'rewarded-timing must fail on a plugin that grants on any close');
  var k = runSuite('kit.test.js', [], {KIT_DIR: dir});
  assert.ok(k.status !== 0 && k.out && k.out.failed > 0, 'kit.test must fail on a plugin paying the wrong growth reward');
});

// ---- 3. make_plugin_scripts.py --check ----
function py(args, cwd) {
  return child.spawnSync('python3', args, {cwd: cwd, encoding: 'utf8', timeout: 60000});
}
function kitCopy(tag) {
  var dir = path.join(work, 'copy-' + tag);
  ['tools', 'plugins-3x', 'parts-3x', 'assets/tiktok-platform', 'build-templates/bytedance-mini-game', 'parts'].forEach(function (rel) {
    fs.cpSync(path.join(KIT, rel), path.join(dir, rel), {recursive: true});
  });
  return dir;
}
function edit(file, from, to) {
  var t = fs.readFileSync(file, 'utf8');
  assert.ok(t.indexOf(from) >= 0, 'mutation anchor missing in ' + file);
  fs.writeFileSync(file, t.replace(from, to));
}
test('check_passes_on_this_kit', function () {
  var r = py([path.join(KIT, 'tools', 'make_plugin_scripts.py'), '--check']);
  assert.strictEqual(r.status, 0, r.stdout);
});
var mutants = [
  ['plugin_core_edited', function (d) { edit(path.join(d, 'plugins-3x', 'RewardedService.plugin.js'), 'requestTimeoutMs', 'requestTimeoutMS'); }, /RewardedService\.plugin\.js: code between BEGIN and END differs/],
  ['plugin_wrapper_edited', function (d) { edit(path.join(d, 'plugins-3x', 'SaveStore.plugin.js'), 'loaded twice: keep the first', 'loaded twice'); }, /SaveStore\.plugin\.js is stale/],
  ['module_changed_plugin_not_regenerated', function (d) { fs.appendFileSync(path.join(d, 'assets', 'tiktok-platform', 'MissionFlow.js'), '// changed\n'); }, /MissionFlow\.plugin\.js: code between BEGIN and END differs/],
  ['touch3x_changed_parts_not_regenerated', function (d) { fs.appendFileSync(path.join(d, 'build-templates', 'bytedance-mini-game', 'tiktok-touch-3x.js'), '\n'); }, /KIT_PARTS_3X\.json is stale/],
  ['storage_guard_changed_parts_not_regenerated', function (d) { fs.appendFileSync(path.join(d, 'parts', 'storage-guard.js'), '\n'); }, /KIT_PARTS_3X\.json is stale/],
  ['parts_hand_edited', function (d) { edit(path.join(d, 'parts-3x', 'KIT_PARTS_3X.json'), '"previous_sha256": []', '"previous_sha256": ["x"]'); }, /KIT_PARTS_3X\.json is stale/],
  ['plugin_missing', function (d) { fs.rmSync(path.join(d, 'plugins-3x', 'TikTokMissionService.plugin.js')); }, /TikTokMissionService\.plugin\.js missing/]
];
var negative = [];
mutants.forEach(function (m) {
  test('check_fails_when_' + m[0], function () {
    var dir = kitCopy(m[0]);
    m[1](dir);
    var r = py([path.join(dir, 'tools', 'make_plugin_scripts.py'), '--check']);
    var caught = r.status === 1 && m[2].test(r.stdout);
    negative.push({name: m[0], caught: caught});
    assert.ok(caught, 'not caught: ' + r.stdout.slice(0, 500));
    var w = py([path.join(dir, 'tools', 'make_plugin_scripts.py')]);
    assert.strictEqual(w.status, 0, w.stderr);
    if (m[0] !== 'plugin_core_edited' && m[0] !== 'plugin_wrapper_edited' && m[0] !== 'parts_hand_edited' && m[0] !== 'plugin_missing') {
      var again = py([path.join(dir, 'tools', 'make_plugin_scripts.py'), '--check']);
      assert.strictEqual(again.status, 0, 'regenerating fixes it: ' + again.stdout.slice(0, 300));
    }
  });
});
test('generation_is_stable', function () {
  var dir = kitCopy('stable');
  var before = fs.readFileSync(path.join(dir, 'parts-3x', 'KIT_PARTS_3X.json'));
  var w = py([path.join(dir, 'tools', 'make_plugin_scripts.py')]);
  assert.strictEqual(JSON.parse(w.stdout).written.length, 0, 'second run writes nothing');
  assert.ok(fs.readFileSync(path.join(dir, 'parts-3x', 'KIT_PARTS_3X.json')).equals(before));
});

// ---- 4. KIT_PARTS_3X.json wiring ----
var GAME_JS = "loadCC();\nfunction loadCC() {\n    require('./web-adapter');\n    require(\"src/polyfills.bundle.js\");\n}\n";
test('parts_cover_touch_storage_and_plugins_only', function () {
  assert.deepStrictEqual(Object.keys(parts.parts).sort(),
    ['missionflow3x', 'missions3x', 'platformconfig3x', 'rewarded3x', 'savestore3x', 'storage3x', 'touch3x']);
  Object.keys(parts.parts).forEach(function (k) {
    var p = parts.parts[k];
    assert.strictEqual(p.engine, 3, k);
    var src = path.join(KIT, p.file.src);
    var sha = require('crypto').createHash('sha256').update(fs.readFileSync(src)).digest('hex');
    assert.strictEqual(sha, p.file.sha256, k + ' sha256 is the kit file');
  });
  assert.ok(/no Cocos 3\.x startup part/.test(parts.startup), 'Q5: no 3.x startup part');
});
test('wiring_lines_are_js_and_anchor_matches_once', function () {
  ['touch3x', 'storage3x'].forEach(function (k) {
    var w = parts.parts[k].wiring;
    assert.strictEqual(w.length, 1, k);
    assert.strictEqual(w[0]['in'], 'game.js');
    new vm.Script(w[0].line, {filename: k + '-line'});
    assert.ok(w[0].line.indexOf('// tiktok-kit:' + k + ':' + parts.version) > 0, k + ' marker');
    var anchor = new RegExp(w[0].insert_before || w[0].insert_after, 'g');
    assert.strictEqual((GAME_JS.match(anchor) || []).length, 1, k + ' anchor once');
    assert.strictEqual((w[0].line.match(anchor) || []).length, 0, k + ' line must not match its own anchor');
  });
  assert.ok(parts.parts.touch3x.wiring[0].insert_before, 'touch goes BEFORE web-adapter');
  assert.ok(parts.parts.storage3x.wiring[0].insert_after, 'storage goes AFTER web-adapter');
});
test('touch_own_markers_hit_known_own_layers_not_kit_or_engine_shapes', function () {
  var m = parts.parts.touch3x.own_markers.map(function (s) { return new RegExp(s); });
  var hit = function (t) { return m.some(function (r) { return r.test(t); }); };
  assert.ok(hit("try { if (typeof tt !== 'undefined') require('./marlow-touch')(tt); } catch (e) {}"), 'Marlows R6 game.js');
  assert.ok(hit("const on = 'onTouch' + suffix;"), 'dynamic onTouch wrapper');
  assert.ok(hit('tt.onTouchStart = function (fn) {};'), 'direct SDK assignment');
  assert.ok(!hit('e.onTouchStart=function(t){this._s.push(t)}'), 'engine-style member assignment is not an own layer');
  assert.ok(!hit(parts.parts.touch3x.wiring[0].line), 'kit wiring line is not an own layer');
});

var failed = results.filter(function (r) { return r.status !== 'passed'; });
console.log(JSON.stringify({suite: 'plugins-3x', passed: results.length - failed.length, failed: failed.length,
  same_cases_on_plugins: counts, check_negative_controls: negative, results: results}, null, 2));
if (failed.length) process.exitCode = 1;
